class Solution {
    unordered_map<int, vector<int>> pos;
public:
    Solution(vector<int>& nums) {
        for (int i = 0; i < (int)nums.size(); ++i) pos[nums[i]].push_back(i);
    }
    int pick(int target) {
        auto& v = pos[target];
        return v[rand() % v.size()];
    }
};

